Let $B = \mathrm{Bohr}(\Gamma, \nu)$ be a regular Bohr set of rank $d$ and suppose that $A\subset B$ has density $\alpha$. Then
\begin{equation*}
T(A, A, A) \geq \exp \left(-\tilde{O}_{\alpha}(d + \alpha^{-1}) \log{2d}\right)\Bigg( \prod_{\gamma\in \Gamma}\frac{\nu(\gamma)}{8}\Bigg)^{\tilde{O}_{\alpha}(1)}.
\end{equation*}

Let $\ensuremath{\mathcal{B}}$ be a regular Bohr set of rank $d$, and let $\ensuremath{\mathcal{A}} \subset \ensuremath{\mathcal{B}}$ of relative density $\alpha$. Let~$B^{\star} = {\ensuremath{\mathcal{B}} \cap T_2\ensuremath{\mathcal{B}} \cap T_3\ensuremath{\mathcal{B}}}$. Then, either 
\begin{equation*}
T(\ensuremath{\mathcal{A}}, \ensuremath{\mathcal{A}}, \ensuremath{\mathcal{A}}) \gg \exp \left(-\tilde{O}_{\alpha}(d \log(2d)\right) \mu(B^{\star})^2
\end{equation*}
or $\ensuremath{\mathcal{A}}$ has a density increment of strength
\begin{equation*}
[1, \alpha^{-1}; \tilde{O}_{\alpha}(1)]
\end{equation*}
with respect to either $B^{\star}$, $T_2^{-1}B^{\star}$ or $T_3^{-1}B^{\star}$.

There is a constant $C>0$ such that, for all $k\geq C$, the following holds. Let $\ensuremath{\mathcal{B}}$ be a regular Bohr set of rank $d$ and suppose that $\ensuremath{\mathcal{A}}\subset \ensuremath{\mathcal{B}}$ has density $\alpha$. Let $\textcolor{blue}{\ensuremath{\mathcal{B}}^{\star} := \ensuremath{\mathcal{B}} \cap T_2\ensuremath{\mathcal{B}} \cap T_3\ensuremath{\mathcal{B}}}$. Either 
\begin{enumerate}
	\item $\alpha \geq 2^{-O(k^2)}$, 
	\item \begin{equation*}
	T(\ensuremath{\mathcal{A}}, \ensuremath{\mathcal{A}}, \ensuremath{\mathcal{A}}) \gg \exp\left(-\tilde{O}_{\alpha}(d \log{2d})\right) \mu(\textcolor{blue}{\ensuremath{\mathcal{B}}^{\star}})^2,
	\end{equation*}
	or
	\item $\ensuremath{\mathcal{A}}$ has a density increment of one of the following strengths \textcolor{blue}{relative to $\ensuremath{\mathcal{B}}_1:=\ensuremath{\mathcal{B}}^{\star}$, $\ensuremath{\mathcal{B}}_2:=T_2^{-1}\ensuremath{\mathcal{B}}^{\star}$ or $\ensuremath{\mathcal{B}}_3:=T_3^{-1}\ensuremath{\mathcal{B}}^{\star}$}: 
	\begin{enumerate}
		\item (small increment) $[\alpha^{O(\varepsilon(k))}, \alpha^{-O(\varepsilon(k))}; \tilde{O}_{\alpha}(1)]$, or
		\item (large increment) $[\alpha^{-1/k}, \alpha^{-1+1/k}; \tilde{O}_{\alpha}(1)]$,
	\end{enumerate}
	where $\varepsilon(k) = \frac{ \log \log \log k}{\log \log k}$.
\end{enumerate}

There is a constant $c>0$ such that the following holds. Let $\ensuremath{\mathcal{B}}$ be a regular Bohr set of rank $d$, let $\ensuremath{\mathcal{A}}\subset \ensuremath{\mathcal{B}}$ have relative density $\alpha$, let $\varepsilon>0$ and suppose that ${B_1, B_2, B_3} \subset \ensuremath{\mathcal{B}}_\rho$ where $\rho \leq c\alpha \varepsilon/d$. Then either 
\begin{enumerate}
	\item ($\ensuremath{\mathcal{A}}$ has almost full density on $B_1$, $B_2$ and $B_3$) there is an $x\in \ensuremath{\mathcal{B}}$ such that 
	\begin{equation*}
	\mathbf{1}_{\ensuremath{\mathcal{A}}} * \mu_{B_i} (x) \geq (1-\varepsilon)\alpha
	\end{equation*}
	for $i=1, 2, 3$, or
	\item (density increment) $\ensuremath{\mathcal{A}}$ has an increment of strength $[\varepsilon, 0; O(1)]$ relative to one of the $B_i$'s.
\end{enumerate}

There is a constant $c\in (0, \tfrac12)$ such that the following holds. Let $0< \alpha\leq 1$. Let~$B$ be a regular Bohr set of rank $d$ and $B'$ a regular Bohr set of rank $\leq 3d$ such that $B' \subset B_{\rho}$, where $\rho = c \alpha/d$. Suppose that $A_1 \subset B$, $A_2\subset T_2^{-1}B'$ and $A_3\subset T_3^{-1}B$, each time with relative density at least $\alpha$. Then 
\begin{enumerate}
	\item either 
\begin{equation*}
T(A_1, A_2, A_3) \gg \alpha^3 \mu(B) \mu(B')
\end{equation*}
	\item or there is a regular Bohr set $B''$ such that $\left\|1_A * \mu_{B''}\right\|_{\infty} \geq (1+c)\alpha$, where 
	\begin{itemize}
		\item $A$ is either $A_1$ or $-T_3A_3$,
		\item and $B''$ is of the form 
		\begin{equation*}
			B'' = B'_{\eta} \cap \widetilde{B}
		\end{equation*}
		for some $\eta \asymp \exp(-\tilde{O}_{\alpha}(1))/d$ and some $\widetilde{B} = \mathrm{Bohr}(\widetilde{\Gamma}, \widetilde{\nu})$ with $|\widetilde{\Gamma}| \leq d'/4$ and $\widetilde{\nu} \geq 1/d'$ on $\widetilde{\Gamma}$, where $d' = \tilde{O}_{\alpha}(\alpha^{-1})$.
	\end{itemize}
\end{enumerate}

There is a constant $c>0$ such that the following holds. Let $k, h, t\geq 20$ be some parameters. 

Let $0< \alpha\leq 1$. Let $B$ be a regular Bohr set of rank $d$, and $B'$ another regular Bohr set, of \textcolor{blue}{rank at most $3d$}, such that \textcolor{blue}{$B' \subset T_3^{-1}B_{\rho}$}, where $\rho \leq c\alpha^2/d$. Let \textcolor{blue}{$A_1 \subset B$, $A_2 \subset T_2^{-1}B$} and $A_3 \subset B'$, each time with relative density in $[\alpha/2, 2\alpha]$. Then \textcolor{blue}{for either $A = A_1$ or $A = T_2A_2$}, one of the following holds 
\begin{enumerate}
	\item (large density) $\alpha \gg 1/k^2$, or
	\item (many solutions) $\textcolor{blue}{T(A_1, A_2, A_3)} \gg \alpha^3 \mu(B) \mu(B')$, or
	\item $A$ has a density increment of strength either 
	\begin{enumerate}
		\item (small increment) $[1, \alpha^{-1/k}; \tilde{O}_{\alpha}(h \log t)]$ or 
		\item (large increment) $[\alpha^{-1/k}, \alpha^{-1+1/k}; \tilde{O}_{\alpha}(h \log t)]$
	\end{enumerate}
	relative to $\textcolor{blue}{T_3B'}$, or
	\item (non-smoothing large spectrum) there is a set $\Delta$ and three quantities ${\rho_{\mathrm{top}}, \rho_{\mathrm{bottom}}, \rho'\in (0, 1)}$ satisfying
	\begin{equation*}
	\rho_{\mathrm{top}} \gg \alpha^{O(1)}(c/dt)^{O(h)}, \quad \rho_{\mathrm{bottom}}\gg (\alpha/d)^{O(1)}, \quad \text{and}\quad \rho' \gg (\alpha/d)^{O(1)},
	\end{equation*}
	such that 
	\begin{enumerate}
		\item $\alpha^{-3 + O(1/k)} \ll |\Delta| \lesssim_{\alpha} \alpha^{-3}$,
		\item there exists an additive framework $\tilde{\Gamma}$ of height $h$ and tolerance $t$ between 
		\begin{equation*}
		\Gamma_{\mathrm{top}} := \Delta_{1/2}(\textcolor{blue}{T_3 B_{\rho_{\mathrm{top}}}'})\quad \text{and}\quad\Gamma_{\mathrm{bottom}} := \Delta_{1/2}(\textcolor{blue}{T_3 B_{\rho_{\mathrm{bottom}}}'}),
		\end{equation*}
		\item $\Delta$ is $\tfrac{1}{4}$-robustly $(\tau, k')$-additively non-smoothing relative to $\tilde{\Gamma}$ for some $\alpha^{2-O(1/k)} \gg \tau \gg \alpha^{2+O(1/k)}$ and $k\geq k' \gg k$, and 
		\item if we let $B'' = (\textcolor{blue}{T_3 B_{\rho_{\mathrm{top}}}'})_{\rho'}$ then for all $\gamma \in\Delta + \Gamma_{\mathrm{top}}$
		\begin{equation*}
		|\widehat{\mu_{A/B}}|^2 \circ |\widehat{\mu_{B''}}|^2 (\gamma) \gg \alpha^{2+O(1/k)} \mu(B)^{-1},
		\end{equation*}
		and
		\item \begin{equation*}
		\Big\|\mathbf{1}_{\Delta} \circ |\widehat{\mu_{B''}}|^2\Big\|_{\infty} \leq 2.
		\end{equation*}
	\end{enumerate}
\end{enumerate}

There is a constant $c > 0$ such that the following holds. Let $0 < \alpha \leq 1$. Let $B$ be a regular Bohr set of rank $d$, and $B'$ another regular Bohr set such that \textcolor{blue}{$T_3B' \subset B_{\rho}$}, with $\rho \leq c\alpha/d$. Let \textcolor{blue}{$A_1 \subset B$, $A_2\subset T_2^{-1}B$} and $A_3 \subset B'$, each time with relative density in $[\alpha/2, 2\alpha]$. Then either 
\begin{enumerate}
	\item (many solutions) $\textcolor{blue}{T(A_1, A_2, A_3)} \geq \tfrac{1}{16} \alpha^3 \mu(B) \mu(B')$, or
	\item (large $L^2$ mass on a spectrum) there is some $\eta \gg \alpha$ such that
	\begin{equation*}
	\sum_{\gamma \in \Delta_\eta (\textcolor{blue}{-T_3A_3})} |\widehat{\mu_{A/B}}(\gamma)|^2 \gtrsim_{\alpha} \eta^{-1} \mu(B)^{-1},
	\end{equation*}
	where \textcolor{blue}{$A$ is either $A_1$ or $T_2A_2$}.
\end{enumerate}

Let $G$ be a finite abelian group and let $T_1, T_2, T_3$ be automorphisms of $G$ such that $T_1 + T_2 + T_3 = 0$. If $A$ is a subset of $G$ without non-trivial solutions\footnote{A solution $(a_1, a_2, a_3)\in A^3$ is trivial if $a_1 = a_2 = a_3$.} to the equation 
\begin{equation}

T_1 a_1 + T_2 a_2 + T_3 a_3 = 0,
\end{equation}
then
\begin{equation*}
|A| \ll \frac{|G|}{(\log|G|)^{1+c}}
\end{equation*}
where $c > 0$ is an absolute constant.\footnote{In particular, the constant $c$ does not depend on $G$ or on the coefficients $T_i$.}
